#include <bits/stdc++.h>
using namespace std;using ll=long long;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<ll>w(n);for(auto&x:w)cin>>x;vector<vector<int>>g(n);vector<pair<int,int>>es;while(m--){int u,v;cin>>u>>v;--u;--v;g[u].push_back(v);es.push_back({u,v});}vector<int>dfn(n),low(n),st,ins(n),bel(n);int tim=0,cc=0;function<void(int)>tarjan=[&](int u){dfn[u]=low[u]=++tim;st.push_back(u);ins[u]=1;for(int v:g[u])if(!dfn[v])tarjan(v),low[u]=min(low[u],low[v]);else if(ins[v])low[u]=min(low[u],dfn[v]);if(low[u]==dfn[u]){while(1){int x=st.back();st.pop_back();ins[x]=0;bel[x]=cc;if(x==u)break;}++cc;}};for(int i=0;i<n;++i)if(!dfn[i])tarjan(i);vector<ll>sum(cc);for(int i=0;i<n;++i)sum[bel[i]]+=w[i];vector<vector<int>>dag(cc);vector<int>in(cc);set<pair<int,int>>seen;for(auto [u,v]:es)if(bel[u]!=bel[v]&&seen.insert({bel[u],bel[v]}).second)dag[bel[u]].push_back(bel[v]),++in[bel[v]];queue<int>q;vector<ll>dp=sum;for(int i=0;i<cc;++i)if(!in[i])q.push(i);ll ans=0;while(!q.empty()){int u=q.front();q.pop();ans=max(ans,dp[u]);for(int v:dag[u]){dp[v]=max(dp[v],dp[u]+sum[v]);if(!--in[v])q.push(v);}}cout<<ans<<'\n';}
